With the final restriction, I would use thread-private histograms followed by a separate reduction kernel—no atomics anywhere. Each worker exclusively owns one histogram row and processes disjoint input positions; in the reduction, each output bin has exactly one writer. Highly skewed keys therefore create no write contention, and 64-bit counters preserve exact counts for any input length representable in 64 bits.

```cpp
// histogram.cu
#include <cuda_runtime.h>
#include <cstddef>
#include <cstdio>
#include <cstdlib>
#include <iostream>
#include <limits>
#include <vector>

using Count = unsigned long long;
static_assert(sizeof(Count) == 8);
static_assert(sizeof(std::size_t) <= sizeof(Count));

constexpr unsigned BLOCKS = 8;
constexpr unsigned THREADS = 128;
constexpr unsigned WORKERS = BLOCKS * THREADS;

#define CHECK(call) do {                                         \
    cudaError_t e = (call);                                       \
    if (e != cudaSuccess) {                                      \
        std::fprintf(stderr, "%s: %s\n", #call,                   \
                     cudaGetErrorString(e));                     \
        std::exit(EXIT_FAILURE);                                 \
    }                                                            \
} while (false)

__global__ void build_private(const unsigned int* keys,
                              std::size_t n,
                              std::size_t bins,
                              Count* partials) {
    const std::size_t worker =
        std::size_t(blockIdx.x) * blockDim.x + threadIdx.x;
    const std::size_t workers = std::size_t(gridDim.x) * blockDim.x;
    Count* mine = partials + worker * bins;

    // Only this worker reads or writes this row in this kernel.
    for (std::size_t b = 0; b < bins; ++b)
        mine[b] = 0;

    std::size_t i = worker;
    while (i < n) {
        ++mine[keys[i]];  // Ordinary increment, not atomic.
        if (n - i <= workers) break;  // Prevent index overflow.
        i += workers;
    }
}

__global__ void reduce_private(const Count* partials,
                               std::size_t bins,
                               Count* counts) {
    const std::size_t first =
        std::size_t(blockIdx.x) * blockDim.x + threadIdx.x;
    const std::size_t stride = std::size_t(gridDim.x) * blockDim.x;

    for (std::size_t b = first; b < bins; b += stride) {
        Count total = 0;
        for (unsigned worker = 0; worker < WORKERS; ++worker)
            total += partials[std::size_t(worker) * bins + b];
        counts[b] = total;  // Exactly one thread owns this bin.
    }
}

int main() {
    // Input: number of bins, followed by keys until EOF.
    unsigned long long raw_bins;
    if (!(std::cin >> raw_bins) || raw_bins == 0 ||
        raw_bins > std::numeric_limits<unsigned int>::max() ||
        raw_bins > std::numeric_limits<std::size_t>::max()
                       / sizeof(Count) / WORKERS) {
        std::cerr << "Invalid number of bins\n";
        return EXIT_FAILURE;
    }
    const std::size_t bins = static_cast<std::size_t>(raw_bins);

    std::vector<unsigned int> keys;
    unsigned long long key;
    while (std::cin >> key) {
        if (key >= raw_bins) {
            std::cerr << "Key outside [0, bins)\n";
            return EXIT_FAILURE;
        }
        keys.push_back(static_cast<unsigned int>(key));
    }
    if (!std::cin.eof()) {
        std::cerr << "Invalid key input\n";
        return EXIT_FAILURE;
    }
    if (keys.size() > std::numeric_limits<std::size_t>::max()
                          / sizeof(unsigned int)) {
        std::cerr << "Input size overflow\n";
        return EXIT_FAILURE;
    }

    unsigned int* device_keys = nullptr;
    Count* partials = nullptr;
    Count* device_counts = nullptr;
    const std::size_t input_bytes = keys.size() * sizeof(unsigned int);
    const std::size_t output_bytes = bins * sizeof(Count);

    CHECK(cudaMalloc(reinterpret_cast<void**>(&partials),
                     output_bytes * WORKERS));
    CHECK(cudaMalloc(reinterpret_cast<void**>(&device_counts),
                     output_bytes));
    if (!keys.empty()) {
        CHECK(cudaMalloc(reinterpret_cast<void**>(&device_keys),
                         input_bytes));
        CHECK(cudaMemcpy(device_keys, keys.data(), input_bytes,
                         cudaMemcpyHostToDevice));
    }

    // Same-stream kernel ordering makes all partial writes visible
    // before reduction starts. No in-kernel barrier is needed.
    build_private<<<BLOCKS, THREADS>>>(
        device_keys, keys.size(), bins, partials);
    CHECK(cudaGetLastError());
    reduce_private<<<BLOCKS, THREADS>>>(partials, bins, device_counts);
    CHECK(cudaGetLastError());
    CHECK(cudaDeviceSynchronize());

    std::vector<Count> counts(bins);
    CHECK(cudaMemcpy(counts.data(), device_counts, output_bytes,
                     cudaMemcpyDeviceToHost));
    for (std::size_t b = 0; b < bins; ++b)
        std::cout << b << ": " << counts[b] << '\n';

    if (device_keys) CHECK(cudaFree(device_keys));
    CHECK(cudaFree(partials));
    CHECK(cudaFree(device_counts));
    return EXIT_SUCCESS;
}
```

Compile and run with a CUDA toolkit and compatible NVIDIA GPU:

```sh
nvcc -std=c++17 histogram.cu -o histogram
printf '4 1 1 1 1 3\n' | ./histogram
```

This prints counts `0, 4, 0, 1`. Every input index belongs to exactly one worker, and each reduction sum is at most the input length, so neither updates nor sums overflow under the stated 64-bit bound. Empty input also works: all private rows are initialized to zero before reduction.

The trade-off is `WORKERS × bins × 8` bytes of scratch space plus reduction work, which suits a small key range. This executable requires the input to fit in memory; larger inputs can be streamed in chunks, retaining each worker’s private histogram across ordered chunk kernels and reducing once at the end.
